mapper.update:

    	update orderitem set
    	postCode = #{postCode},
    	address1 = #{address1},
    	address2 = #{address2},
    	address3 = #{address3},
    	phone = #{phone},
    	email = #{email}
		where 1 = 1
		and id = #{id}
		and orderId = #{orderId}


    	update orderitem


		charge = charge - #{charge},


	    	orderPrice = orderPrice - #{price},
	    	cancelPrice = cancelPrice + #{price}
			where 1 = 1
			and orderId = #{orderId}
